    70      public async Task RefreshAsync(CancellationToken cancellationToken = default)
    71      {
    72          await _refreshLock.WaitAsync(cancellationToken);
    73  
    74          try
    75          {
    76              await using var scope = scopeFactory.CreateAsyncScope();
    77              var tenantsProvider = scope.ServiceProvider.GetRequiredService<ITenantsProvider>();
    78              var currentTenants = await GetTenantsDictionaryAsync(cancellationToken);
    79              var currentTenantIds = currentTenants.Keys;
    80              var tenantsFromProvider = (await tenantsProvider.ListAsync(cancellationToken)).ToList();
    81              var newTenants = tenantsFromProvider.Count == 0
    82                  ? new Dictionary<string, Tenant> { [Tenant.DefaultTenantId] = Tenant.Default }
    83                  : tenantsFromProvider.ToDictionary(x => x.Id.EmptyIfNull());
    84              var newTenantIds = newTenants.Keys;
    85              var removedTenantIds = currentTenantIds.Except(newTenantIds).ToArray();
    86              var addedTenantIds = newTenantIds.Except(currentTenantIds).ToArray();
